"use client";

import { cloneElement, useLayoutEffect, useRef, useState, type MouseEvent, type ReactElement, type ReactNode } from "react";

import { analyseLink, isScriptLink, isTrusted, type ExternalLinkLabels } from "@rhs-ui/application/external-link-dialog/link";
import { ExternalLinkPanel } from "@rhs-ui/application/external-link-dialog/panel";
import { AlertDialog, AlertDialogContent } from "@rhs-ui/primitives/alert-dialog";
import { cn } from "@/lib/utils";

export type { LinkInfo, ExternalLinkLabels } from "@rhs-ui/application/external-link-dialog/link";
export { ExternalLinkPanel, type ExternalLinkPanelProps } from "@rhs-ui/application/external-link-dialog/panel";

export interface ExternalLinkDialogProps {
  /** Where the link goes. Give it together with `trigger` (or with `open`, to ask without a trigger). Leave it out with `intercept`: the address is read from the link that was clicked. */
  href?: string;
  /** The element that asks the question when it is clicked: usually a link, `<a href={href}>`, or a button. A plain click is caught; a click with Ctrl, Cmd, Shift or the middle button goes through, because the browser then shows the address itself. */
  trigger?: ReactElement<{ onClick?: (event: MouseEvent<HTMLElement>) => void }>;
  /** Wrap content instead of one trigger: a click on any link inside it that leaves your site asks first. Links on your own site, `mailto:` and `tel:` links, and hosts in `trustedHosts` pass straight through, and a `javascript:` or `data:` link is stopped. */
  intercept?: boolean;
  /** The content to watch in `intercept` mode: a comment, a bio, a message. */
  children?: ReactNode;
  /** Hosts that skip the dialog: `docs.northwind.dev` matches exactly, `*.northwind.dev` matches every subdomain. A link to one of them just works. */
  trustedHosts?: readonly string[];
  /** Continue was chosen, with the address that opens. It opens in a new tab with `noopener noreferrer` either way; this is for counting it. */
  onContinue?: (href: string) => void;
  /** Go back was chosen, or Escape was pressed. */
  onCancel?: () => void;
  /** Adds "Don't ask again for this site" and calls this with the host when Continue is chosen with the box ticked. Store it however you like, and pass it back in `trustedHosts`. */
  onTrust?: (host: string) => void;
  /** Whether the dialog is open, when you control it. */
  open?: boolean;
  /** Whether it is open to begin with. */
  defaultOpen?: boolean;
  /** Called when it opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** The words the dialog says, for translation. */
  labels?: ExternalLinkLabels;
  /** Classes for the wrapper in `intercept` mode, which has no box of its own unless you give it one. */
  className?: string;
}

const isPlainClick = (event: MouseEvent) => event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey;

/**
 * The pause before leaving your site through a link somebody else wrote: in comments, bios and messages the destination is
 * not yours. It shows where the link really goes with the host in bold, says "This link goes to another website", and
 * offers Continue or Go back, with Go back in focus. A host with look-alike letters is shown in its ASCII form under a
 * warning. Give it a `trigger` and an `href` for one link, or wrap the content with `intercept` and every outside link in it
 * asks. `trustedHosts` skip the dialog, and "Don't ask again for this site" calls `onTrust` so you decide how to store it. When it
 * closes, focus goes back to the link or button that was clicked, and it never grows taller than the screen: it scrolls.
 */
export function ExternalLinkDialog({ href, trigger, intercept = false, children, trustedHosts = [], onContinue, onCancel, onTrust, open, defaultOpen = false, onOpenChange, labels, className }: ExternalLinkDialogProps) {
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const [asked, setAsked] = useState<string | null>(null);
  const continued = useRef(false);
  const returnTo = useRef<HTMLElement | SVGElement | null>(null);
  const isOpen = open ?? ownOpen;
  const target = intercept ? asked : (href ?? asked);
  const shown = isOpen && target !== null;

  // A dialog that is opened from the outside (`open`) was not asked by a click here: it remembers who had focus, before it takes focus into itself.
  useLayoutEffect(() => {
    if (!shown || returnTo.current) return;
    const active = document.activeElement;
    if (active instanceof HTMLElement && active !== document.body) returnTo.current = active;
  }, [shown]);

  function change(next: boolean) {
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
    if (next) return;
    // Continue closes the dialog too; only the other ways out are a "no".
    if (!continued.current) onCancel?.();
    continued.current = false;
  }

  /** Opens the question for an address. `from` is the link or button that was clicked: focus goes back to it when the dialog closes. */
  function ask(address: string, from: HTMLElement | SVGElement | null) {
    returnTo.current = from;
    setAsked(address);
    change(true);
  }

  function clickedTrigger(event: MouseEvent<HTMLElement>) {
    trigger?.props.onClick?.(event);
    if (event.defaultPrevented || !isPlainClick(event) || href === undefined) return;
    const info = analyseLink(href);
    if (!info) return;
    if (isTrusted(info.host, trustedHosts)) {
      // A link opens itself. A button that stands for one has to do it by hand.
      if (!event.currentTarget.closest("a[href]")) {
        onContinue?.(info.href);
        window.open(info.href, "_blank", "noopener,noreferrer");
      }
      return;
    }
    event.preventDefault();
    ask(href, event.currentTarget);
  }

  function clickedInside(event: MouseEvent<HTMLElement>) {
    const anchor = (event.target as Element | null)?.closest?.("a[href]");
    if (!anchor || !event.currentTarget.contains(anchor) || event.defaultPrevented || !isPlainClick(event)) return;
    // The attribute, not anchor.href: the property is already the ASCII form, and the written form is what shows a look-alike.
    const raw = (anchor.getAttribute("href") ?? "").trim();
    if (isScriptLink(raw)) {
      event.preventDefault();
      return;
    }
    const written = raw.startsWith("//") ? `${window.location.protocol}${raw}` : raw;
    const info = analyseLink(written);
    if (!info) return;
    if (new URL(info.href).origin === window.location.origin || isTrusted(info.host, trustedHosts)) return;
    event.preventDefault();
    ask(written, anchor instanceof HTMLElement || anchor instanceof SVGElement ? anchor : null);
  }

  return (
    <>
      {intercept ? (
        <div data-slot="external-link-dialog" className={cn("contents", className)} onClick={clickedInside}>
          {children}
        </div>
      ) : trigger ? (
        cloneElement(trigger, { onClick: clickedTrigger })
      ) : null}
      <AlertDialog open={shown} onOpenChange={change}>
        {target !== null ? (
          <AlertDialogContent
            // The dialog is never taller than the screen and scrolls when it has to (a phone on its side, larger text, a warning or two), so Go back and Continue are always reachable. `fixed` is what the primitive already sets.
            className="fixed max-h-[calc(100dvh-2rem)] gap-0 overflow-y-auto p-0 sm:max-w-md"
            // There is no trigger inside the dialog to give focus back to: it goes to the link or button that was clicked, if it is still on the page.
            onCloseAutoFocus={(event) => {
              event.preventDefault();
              const back = returnTo.current;
              returnTo.current = null;
              if (back?.isConnected) back.focus({ preventScroll: true });
            }}
          >
            <ExternalLinkPanel
              href={target}
              labels={labels}
              onTrust={onTrust}
              onContinue={(address) => {
                continued.current = true;
                onContinue?.(address);
              }}
            />
          </AlertDialogContent>
        ) : null}
      </AlertDialog>
    </>
  );
}

"use client";

import { useId, useState, type ComponentProps, type ReactNode } from "react";

import { IconExternal, IconShieldAlert, IconWarning } from "@rhs-ui/icons";
import { analyseLink, DEFAULT_LABELS, type ExternalLinkLabels } from "@rhs-ui/application/external-link-dialog/link";
import { AlertDialogAction, AlertDialogCancel, AlertDialogDescription, AlertDialogTitle } from "@rhs-ui/primitives/alert-dialog";
import { Button, buttonVariants } from "@rhs-ui/primitives/button";
import { Checkbox } from "@rhs-ui/primitives/checkbox";
import { Label } from "@rhs-ui/primitives/label";
import { AS_CHILD } from "@rhs-ui/primitives/render-prop";
import { cn } from "@/lib/utils";

export interface ExternalLinkPanelProps extends Omit<ComponentProps<"div">, "children"> {
  /** The address the link leads to, as it was written. Anything that is not an http or https address gets a message and no Continue button. */
  href: string;
  /** Draw the panel on its own (a page, a sheet, a preview) instead of inside an AlertDialog. The title and the buttons are then plain elements. */
  standalone?: boolean;
  /** Continue was chosen. The link itself opens in a new tab; this is for counting it. */
  onContinue?: (href: string) => void;
  /** Go back was chosen. Inside a dialog the dialog reports it. */
  onCancel?: () => void;
  /** Shows "Don't ask again for this site" and calls this with the host when Continue is chosen with the box ticked. How the host is remembered is up to you. */
  onTrust?: (host: string) => void;
  /** The words the panel says, for translation. */
  labels?: ExternalLinkLabels;
}

/** The title and the line under it: Radix names the dialog from them when the panel is in one, and plain elements stand in when it is not. */
function Heading({ standalone, className, children }: { standalone: boolean; className: string; children: ReactNode }) {
  return standalone ? <h2 className={className}>{children}</h2> : <AlertDialogTitle className={className}>{children}</AlertDialogTitle>;
}

function Lede({ standalone, className, children }: { standalone: boolean; className: string; children: ReactNode }) {
  return standalone ? <p className={className}>{children}</p> : <AlertDialogDescription className={className}>{children}</AlertDialogDescription>;
}

/** A warning: what is wrong, and then the real host on a line of its own in code type, so a long name is not mistaken for the words around it. */
function Warning({ title, body, host }: { title: string; body: string; host: string }) {
  return (
    <div role="alert" className="flex items-start gap-2.5 rounded-lg border border-destructive/40 bg-destructive/5 px-3.5 py-3">
      <IconShieldAlert aria-hidden="true" className="mt-0.5 size-4 shrink-0 text-destructive" />
      <div className="grid min-w-0 gap-1.5 text-sm">
        {/* The destructive colour a little darker, so it holds 4.5:1 on its own tinted background. */}
        <p className="font-medium text-[color-mix(in_oklch,var(--destructive),var(--foreground)_20%)]">{title}</p>
        <p className="leading-relaxed text-muted-foreground">{body}</p>
        <code className="block rounded-md bg-background px-2.5 py-1.5 font-mono text-[0.8125rem] font-medium break-all text-foreground">{host}</code>
      </div>
    </div>
  );
}

/**
 * The question behind an external link: where it really goes, with the host in bold so a long address cannot hide it,
 * the words "This link goes to another website", and the two answers, Go back (which has focus) and Continue. An address
 * built to mislead gets a warning in words: a host with look-alike letters is shown as the ASCII name the browser will
 * really ask for, and a user name in front of the host is called out. Continue is a real link that opens a new tab with
 * `noopener noreferrer`. Use it inside an AlertDialog, or with `standalone` anywhere else.
 */
export function ExternalLinkPanel({ href, standalone = false, onContinue, onCancel, onTrust, labels, className, ...props }: ExternalLinkPanelProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const id = useId();
  const [trust, setTrust] = useState(false);
  const info = analyseLink(href);
  const warned = info !== null && (info.lookalike || info.hasCredentials);
  const variant = warned ? "destructive" : "default";

  const link = info ? (
    <a
      href={info.href}
      target="_blank"
      rel="noopener noreferrer"
      className={standalone ? buttonVariants({ variant }) : undefined}
      onClick={() => {
        if (trust) onTrust?.(info.host);
        onContinue?.(info.href);
      }}
    >
      {words.continue}
      <span className="sr-only"> {words.newTab}</span>
    </a>
  ) : null;

  return (
    <div data-slot="external-link-panel" data-warned={warned || undefined} className={cn("grid gap-5 p-6", className)} {...props}>
      <div className="flex items-start gap-3.5">
        <span
          aria-hidden="true"
          className={cn("grid size-10 shrink-0 place-items-center rounded-xl border [&_svg]:size-[1.125rem]", warned || !info ? "border-destructive/40 bg-destructive/5 text-destructive" : "border-border bg-muted text-foreground")}
        >
          {warned || !info ? <IconShieldAlert /> : <IconExternal />}
        </span>
        <div className="grid min-w-0 gap-1 pt-px">
          <Heading standalone={standalone} className="text-lg leading-tight font-semibold tracking-[-0.02em]">
            {info ? words.title : words.invalidTitle}
          </Heading>
          <Lede standalone={standalone} className="text-sm leading-relaxed text-muted-foreground">
            {info ? words.description : words.invalidBody}
          </Lede>
        </div>
      </div>

      {info ? (
        <dl className="grid gap-1.5">
          <dt className="text-xs font-medium text-muted-foreground">{words.destination}</dt>
          <dd className="relative m-0 max-h-32 overflow-y-auto rounded-lg border border-border bg-muted/40 px-3.5 py-3 font-mono text-[0.8125rem] leading-relaxed [overflow-wrap:anywhere]">
            <span className="text-muted-foreground">
              {info.secure ? "https://" : "http://"}
              {info.credentials}
            </span>
            <strong className="font-semibold text-foreground">{info.lookalike ? info.written : info.host}</strong>
            <span className="text-muted-foreground">
              {info.port}
              {info.rest}
            </span>
          </dd>
          {!info.secure ? (
            <dd className="m-0 flex items-center gap-1.5 text-xs text-muted-foreground">
              <IconWarning aria-hidden="true" className="size-3.5 shrink-0" />
              {words.insecure}
            </dd>
          ) : null}
        </dl>
      ) : null}

      {info?.lookalike ? <Warning title={words.lookalikeTitle} body={words.lookalikeBody} host={info.host} /> : null}

      {info?.hasCredentials ? <Warning title={words.credentialsTitle} body={words.credentialsBody} host={info.host} /> : null}

      {/* A host that is built to mislead is never offered for trust: the box is only for sites that are what they say. */}
      {info && onTrust && !warned ? (
        <div className="flex items-center gap-2.5">
          <Checkbox id={`${id}-trust`} checked={trust} onCheckedChange={(next) => setTrust(next === true)} />
          <Label htmlFor={`${id}-trust`} className="font-normal">
            {words.trust}
          </Label>
        </div>
      ) : null}

      {/* Stacked on a phone the main answer comes first, except when the link is suspect: then the safe one does. */}
      <div className={cn("flex gap-2 sm:flex-row sm:justify-end", warned ? "flex-col" : "flex-col-reverse")}>
        {standalone ? (
          <Button type="button" variant="outline" onClick={onCancel}>
            {words.cancel}
          </Button>
        ) : (
          <AlertDialogCancel>{words.cancel}</AlertDialogCancel>
        )}
        {link && !standalone ? (
          <AlertDialogAction {...AS_CHILD} variant={variant}>
            {link}
          </AlertDialogAction>
        ) : (
          link
        )}
      </div>
    </div>
  );
}

/**
 * What the external link dialog needs to know about an address: where it really goes, and whether anything about it is
 * built to mislead. Plain functions with no state and no hook, so a Server Component can use them too.
 */

/** The words the dialog says, for translation. Each has a default in English. */
export interface ExternalLinkLabels {
  /** The question the dialog asks. Default "Leave this site?" */
  title?: string;
  /** The line under it. Default "This link goes to another website. Check where it leads before you continue." */
  description?: string;
  /** The small heading over the address. Default "Destination". */
  destination?: string;
  /** The heading of the warning for an address with letters that are not plain ASCII. Default "This address uses look-alike characters". */
  lookalikeTitle?: string;
  /** What that warning says. It ends the sentence the real host follows, on a line of its own. */
  lookalikeBody?: string;
  /** The heading of the warning for an address with a name in front of the host. Default "This address hides where it goes". */
  credentialsTitle?: string;
  /** What that warning says. It ends the sentence the site the link really goes to follows, on a line of its own. */
  credentialsBody?: string;
  /** A quiet note under an address that does not use https. Default "This site does not use a secure connection." */
  insecure?: string;
  /** The heading when the address is not a web address at all. Default "This link cannot be opened" */
  invalidTitle?: string;
  /** What that says. Default "It is not a web address, so there is nothing safe to open." */
  invalidBody?: string;
  /** The checkbox, shown when you pass `onTrust`. Default "Don't ask again for this site". */
  trust?: string;
  /** The safe answer, which has focus. Default "Go back". */
  cancel?: string;
  /** The other answer, which opens the link in a new tab. Default "Continue". */
  continue?: string;
  /** Said to screen readers after "Continue": the link opens in a new tab. Default "(opens in a new tab)". */
  newTab?: string;
}

export const DEFAULT_LABELS = {
  title: "Leave this site?",
  description: "This link goes to another website. Check where it leads before you continue.",
  destination: "Destination",
  lookalikeTitle: "This address uses look-alike characters",
  lookalikeBody: "Some letters are not the ones they appear to be, a common way to imitate a site you trust. The browser will really go to:",
  credentialsTitle: "This address hides where it goes",
  credentialsBody: "The part before the @ is a user name, not the site. The link really goes to:",
  insecure: "This site does not use a secure connection.",
  invalidTitle: "This link cannot be opened",
  invalidBody: "It is not a web address, so there is nothing safe to open.",
  trust: "Don't ask again for this site",
  cancel: "Go back",
  continue: "Continue",
  newTab: "(opens in a new tab)",
} satisfies Required<ExternalLinkLabels>;

export interface LinkInfo {
  /** The address as the browser asks for it: the host in its ASCII form, the path and query as they are sent. */
  href: string;
  /** The host as the browser asks for it, lower case and without a port. A look-alike host shows up here as `xn--` labels. */
  host: string;
  /** The host as it was written, which can hold letters that are not ASCII. */
  written: string;
  /** The port, with its colon, when the address names one: ":8443". */
  port: string;
  /** Everything after the host: the path, the query and the fragment. Empty for a bare host. */
  rest: string;
  /** Whether the address uses https. */
  secure: boolean;
  /** The host holds letters that are not plain ASCII, so it can imitate another site. */
  lookalike: boolean;
  /** The address has a user name in front of the host (`https://shop.example@other.example`), which hides where it goes. */
  hasCredentials: boolean;
  /** What stands in front of the host as it was written, with its @: "shop.example@". Empty when there is nothing. */
  credentials: string;
}

/** What stands between `://` and the next slash as it was typed: a user name and an @ if there are any, the host, and the port. */
function authorityOf(raw: string): string {
  return /^[a-z][a-z\d+.-]*:[/\\]{2}([^/\\?#]*)/i.exec(raw)?.[1] ?? "";
}

/** The host out of an authority, as it was typed, with the user name and the port taken off. */
function writtenHost(authority: string): string {
  const hostPort = authority.slice(authority.lastIndexOf("@") + 1);
  const bracketed = /^\[[^\]]*\]/.exec(hostPort);
  return (bracketed ? bracketed[0] : hostPort.replace(/:\d*$/, "")).toLowerCase();
}

/**
 * Reads an address the way a browser does and reports what is worth showing: the real host, the host as written, and
 * whether it is built to mislead (non-ASCII letters, a user name in front of the host). Returns null for anything that is
 * not an http or https address, so a `javascript:` or `data:` link never gets a Continue button.
 */
export function analyseLink(input: string): LinkInfo | null {
  const raw = input.trim();
  let url: URL;
  try {
    url = new URL(raw);
  } catch {
    return null;
  }
  if (url.protocol !== "https:" && url.protocol !== "http:") return null;
  const host = url.hostname.toLowerCase();
  const authority = authorityOf(raw);
  const written = writtenHost(authority) || host;
  const lookalike = /[^\u0000-\u007f]/.test(written) || host.split(".").some((label) => label.startsWith("xn--"));
  const at = authority.lastIndexOf("@");
  return {
    href: url.href,
    host,
    written,
    port: url.port ? `:${url.port}` : "",
    rest: `${url.pathname === "/" ? "" : url.pathname}${url.search}${url.hash}`,
    secure: url.protocol === "https:",
    lookalike,
    hasCredentials: url.username !== "" || url.password !== "",
    credentials: at >= 0 ? authority.slice(0, at + 1) : "",
  };
}

/**
 * Whether a host is on the list that skips the dialog. An entry is a host (`docs.northwind.dev`) that has to match
 * exactly, or `*.northwind.dev` for every subdomain of it (not the bare domain: list that as well if you want it).
 */
export function isTrusted(host: string, trusted: readonly string[]): boolean {
  const name = host.toLowerCase();
  return trusted.some((entry) => {
    const pattern = entry.trim().toLowerCase();
    if (!pattern) return false;
    return pattern.startsWith("*.") ? name.endsWith(pattern.slice(1)) : name === pattern;
  });
}

/** An address that runs code or carries data instead of leading somewhere. Such a link is stopped, never asked about. */
export function isScriptLink(raw: string): boolean {
  return /^[\s\u0000-\u001f]*(javascript|data|vbscript):/i.test(raw);
}
